/* Item 247 — pilot course and branching pathway. */
(()=>{const d=window.ATLAS_ALGORITHM_DATA;if(!d)return;d.sources.diab247={"code": "CEEDMM · Item 247", "title": "Diabète et complications — référentiel du collège", "url": "https://www.sfendocrino.org/item-247-diabete-sucre-de-types-1-et-2-de-lenfant-et-de-ladulte-complications/"};d.algorithms.push({"id": "diabete-247", "sdd": 208, "title": "Devant une hyperglycémie", "items": [247], "scope": "Orientation initiale · Urgences métaboliques, confirmation du diabète et suite de la prise en charge.", "sddUrl": "https://livret.uness.fr/lisa/2026/Accueil", "sddLabel": "Ouvrir les situations de départ LiSA ↗", "summary": "Évaluer la gravité, rechercher cétose et acidose, puis organiser la prise en charge.", "provenance": "Cours Notion et fiche ATLAS 247 · CEEDMM, CNPU et actualisations citées dans les objectifs · Relecture du 12/10/2026.", "nodes": [{"id": "entry", "title": "Évaluer immédiatement la situation", "actions": ["Mesurer la glycémie ; examiner conscience, respiration et hydratation.", "Repérer enfant, grossesse et traitements."], "body": ["Vomissements, douleur abdominale, dyspnée, déshydratation ou trouble de conscience font rechercher une décompensation.", "Si la mesure révèle une hypoglycémie, resucrer immédiatement ; voir le cours associé."], "course": ["247-16", "247-17", "247-25"], "refs": ["diab247"], "choices": [{"label": "Détresse ou trouble de conscience", "to": "urgent"}, {"label": "Enfant ou grossesse", "to": "particulier"}, {"label": "Pas de détresse immédiate", "to": "bilan"}], "kind": null, "why": "La décision repose sur les signes cliniques et biologiques recueillis. Le cours associé précise les critères, les pièges et les situations particulières.", "tree": {"title": "Évaluer immédiatement la situation", "actions": ["Mesurer la glycémie ; examiner conscience, respiration et hydratation.", "Repérer enfant, grossesse et traitements."]}}, {"id": "urgent", "title": "Stabiliser et orienter en urgence", "actions": ["Alerter, surveiller et obtenir une voie veineuse.", "Bilan métabolique sans retarder les premiers soins."], "body": ["Prise en charge hospitalière ; réanimation selon défaillances. Rechercher et traiter le facteur déclenchant.", "La glycémie seule ne permet pas de distinguer acidocétose et état hyperosmolaire."], "course": ["247-16", "247-19"], "refs": ["diab247"], "choices": [], "kind": "urgent", "why": "La décision repose sur les signes cliniques et biologiques recueillis. Le cours associé précise les critères, les pièges et les situations particulières.", "tree": {"title": "Stabiliser et orienter en urgence", "actions": ["Alerter, surveiller et obtenir une voie veineuse.", "Bilan métabolique sans retarder les premiers soins."]}}, {"id": "particulier", "title": "Utiliser la filière spécialisée", "actions": ["Enfant : avis pédiatrique immédiat.", "Grossesse : avis diabétologique et obstétrical."], "body": ["Les débits, les objectifs et la surveillance nécessitent un protocole adapté. Ne pas transposer les volumes adultes à l’enfant."], "course": ["247-18", "247-5"], "refs": ["diab247"], "choices": [], "kind": "urgent", "why": "La décision repose sur les signes cliniques et biologiques recueillis. Le cours associé précise les critères, les pièges et les situations particulières.", "tree": {"title": "Utiliser la filière spécialisée", "actions": ["Enfant : avis pédiatrique immédiat.", "Grossesse : avis diabétologique et obstétrical."]}}, {"id": "bilan", "title": "Rechercher cétose, acidose et hyperosmolalité", "actions": ["Cétonémie, pH veineux, bicarbonates et ionogramme.", "Évaluer fonction rénale, potassium et facteur déclenchant."], "body": ["Une ACD est possible avec une glycémie peu élevée, notamment sous iSGLT2.", "Les formes mixtes existent. Si les critères ne sont pas disponibles, compléter le bilan avant de choisir."], "course": ["247-19", "247-16"], "refs": ["diab247"], "choices": [{"label": "Cétose + acidose", "to": "acd"}, {"label": "Hyperosmolalité majeure sans ACD", "to": "ehh"}, {"label": "Pas de décompensation aiguë", "to": "confirmer"}], "kind": null, "why": "La décision repose sur les signes cliniques et biologiques recueillis. Le cours associé précise les critères, les pièges et les situations particulières.", "tree": {"title": "Rechercher cétose, acidose et hyperosmolalité", "actions": ["Cétonémie, pH veineux, bicarbonates et ionogramme.", "Évaluer fonction rénale, potassium et facteur déclenchant."]}}, {"id": "acd", "title": "Traiter l’acidocétose à l’hôpital", "actions": ["Réhydrater ; vérifier et corriger le potassium.", "Insuline selon protocole, glucose ajouté si nécessaire."], "body": ["Poursuivre jusqu’à résolution de la cétose et de l’acidose ; ne pas arrêter sur la seule normalisation de la glycémie.", "Surveiller et traiter le facteur déclenchant. Adapter si hyperosmolalité associée."], "course": ["247-29", "247-16", "247-31"], "refs": ["diab247"], "choices": [], "kind": "urgent", "why": "La décision repose sur les signes cliniques et biologiques recueillis. Le cours associé précise les critères, les pièges et les situations particulières.", "tree": {"title": "Traiter l’acidocétose à l’hôpital", "actions": ["Réhydrater ; vérifier et corriger le potassium.", "Insuline selon protocole, glucose ajouté si nécessaire."]}}, {"id": "ehh", "title": "Corriger progressivement l’état hyperosmolaire", "actions": ["Réhydrater avec prudence selon le terrain.", "Surveiller osmolalité, électrolytes et état neurologique."], "body": ["Adapter l’insuline, les apports et la prévention thromboembolique. Rechercher infection, accès insuffisant aux boissons et iatrogénie.", "Le coma n’est pas nécessaire au diagnostic. Un relais hypotonique n’est pas automatique."], "course": ["247-30", "247-19", "247-31"], "refs": ["diab247"], "choices": [], "kind": "urgent", "why": "La décision repose sur les signes cliniques et biologiques recueillis. Le cours associé précise les critères, les pièges et les situations particulières.", "tree": {"title": "Corriger progressivement l’état hyperosmolaire", "actions": ["Réhydrater avec prudence selon le terrain.", "Surveiller osmolalité, électrolytes et état neurologique."]}}, {"id": "confirmer", "title": "Confirmer le diabète et préciser son type", "actions": ["Interpréter la glycémie veineuse et les symptômes.", "Rechercher insulinopénie, contexte secondaire et antécédents."], "body": ["Sans symptôme, une glycémie à jeun ≥ 1,26 g/L doit être confirmée. Avec syndrome cardinal et glycémie ≥ 2 g/L, ne pas attendre deux prélèvements à jeun.", "Une hyperglycémie de stress doit être réévaluée après la phase aiguë. Ni âge ni surpoids n’excluent un DT1."], "course": ["247-3", "247-2"], "refs": ["diab247"], "choices": [{"label": "Insulinopénie / DT1 suspecté", "to": "dt1"}, {"label": "DT2 probable, situation stable", "to": "dt2"}, {"label": "Type ou diagnostic incertain", "to": "incertain"}], "kind": null, "why": "La décision repose sur les signes cliniques et biologiques recueillis. Le cours associé précise les critères, les pièges et les situations particulières.", "tree": {"title": "Confirmer le diabète et préciser son type", "actions": ["Interpréter la glycémie veineuse et les symptômes.", "Rechercher insulinopénie, contexte secondaire et antécédents."]}}, {"id": "dt1", "title": "Organiser l’insulinothérapie et l’éducation", "actions": ["Avis diabétologique rapide ; insuline sans retard si nécessaire.", "Apprendre surveillance, injections et conduite en cas d’hypoglycémie."], "body": ["Le plan inclut matériel de secours, cétonémie, adaptation aux repas et jours de maladie."], "course": ["247-20", "247-21", "247-22", "247-31"], "refs": ["diab247"], "choices": [], "kind": "finish", "why": "La décision repose sur les signes cliniques et biologiques recueillis. Le cours associé précise les critères, les pièges et les situations particulières.", "tree": {"title": "Organiser l’insulinothérapie et l’éducation", "actions": ["Avis diabétologique rapide ; insuline sans retard si nécessaire.", "Apprendre surveillance, injections et conduite en cas d’hypoglycémie."]}}, {"id": "dt2", "title": "Personnaliser la prise en charge du DT2", "actions": ["Fixer la cible avec le patient.", "Agir sur mode de vie et risque cardio-rénal."], "body": ["Choisir le traitement selon glycémie, comorbidités, poids, risque d’hypoglycémie et préférences."], "course": ["247-23", "247-24", "247-31"], "refs": ["diab247"], "choices": [], "kind": "finish", "why": "La décision repose sur les signes cliniques et biologiques recueillis. Le cours associé précise les critères, les pièges et les situations particulières.", "tree": {"title": "Personnaliser la prise en charge du DT2", "actions": ["Fixer la cible avec le patient.", "Agir sur mode de vie et risque cardio-rénal."]}}, {"id": "incertain", "title": "Compléter l’enquête sans conclure trop vite", "actions": ["Revoir traitements, contexte aigu et présentation atypique.", "Organiser contrôle et avis spécialisé selon la situation."], "body": ["Une donnée manquante n’est pas un résultat normal. La priorité reste le traitement de toute décompensation."], "course": ["247-2", "247-3"], "refs": ["diab247"], "choices": [], "kind": "uncertain", "why": "La décision repose sur les signes cliniques et biologiques recueillis. Le cours associé précise les critères, les pièges et les situations particulières.", "tree": {"title": "Compléter l’enquête sans conclure trop vite", "actions": ["Revoir traitements, contexte aigu et présentation atypique.", "Organiser contrôle et avis spécialisé selon la situation."]}}]});})();
